          "ルミナス自身は魔王として迎えられ、西方を纏め上げた実績を高く評価されていたが、その後にスカウトされた人材に舐めた態度を取る者が多かったため、代打としてロイを魔王に仕立て上げ、眷属名を与えて魔王ヴァレンタインと名乗らせていた。リムルが“魔王達の宴”に呼ばれた時も静観する姿勢をとっていたが、ヴェルドラとミリムに正体をバラされたことで表舞台に復帰、八星魔王の一柱として再び魔王の座に返り咲いた。",
