          "そして何より彼を最強たらしめる所以が、彼の持つ『傲慢之王』であり、その権能の効果により一度見た能力の完全再現を可能にする。これにより太古の昔から現在に至るまで、数多の強者から権能を学び取ってきており、その結果として、ありとあらゆる状況に対応できるようになっている。",
