          "“魔王”を適度な恐怖を与えることで人類社会に緊張感を持たせるシステムとして成立させると、それに対する抑止力として“勇者”が生まれ、彼の前にも“始まりの勇者”ルドラ・ナスカが現れる。魔王討伐を掲げたルドラは彼のライバルとなり、次第に互いを認め合う友となる。そこでルドラは、自らの野望を実現させるために、互いの直接対決ではなく駒を使った世界の覇権争いを提案する。",
          "ギィは“調停者”として世界のバランスを取りながら、自身の駒として魔王達を増やし、それはやがて十大魔王、そして八星魔王と呼ばれるようになる。また新星であるリムルが既存の恐怖による管理社会ではなく、経済の掌握による管理社会を打ち立てると、西側諸国の管理をリムルに一任。そして彼らの天上のゲームもまた、リムルによってルドラ率いる東の帝国をも打ち倒されることによって幕を降ろした。",
