          "ギィと暮らすようになり、平穏な日々が過ぎていったが、ある日現れた“勇者”ルドラ¹に本気で戦う姿のギィを見て、自身の中にある“嫉妬”を自覚。力を欲した彼女は『嫉妬之王』を獲得し、そしてギィを試すという初心を平穏な暮らしの中で忘れないよう、2つの権能を駆使して自分の心核を凍てつかせ、迷いを捨てるように感情を封印した。",
