          "司るの属性は“氷”とされているが、その固有の権能は『停止』。物質の運動状態を、そのまま静止させることができ、兄から譲られた『忍耐之王』の『固定』と併用することで、無敵といえる防御力を誇っている。得意とするのは、大気中の水分子のみを凝縮させて創り出す氷の壁であり、ヴェルザードは結果として生み出されるその“氷”を使って、その本質をごまかしていた。",
