          "性格は、ただ純粋に自己の知的好奇心を満たすために、善行も悪行も関係なく、何だって行う究極の利己主義者（エゴイスト）。その所業は悪辣で、道義を無視した邪悪な実験の数々によって、数多の災禍が世界中に巻き起こっている。人の心など持ち合わせていない史上最低の愉快犯として、誰からも忌み嫌われ、レイン¹は彼がルミナスに滅ぼされた時には祝杯をあげたほど嫌っていた。",
