          "そんな中、時期も原因も不明だが、彼が星幽体のみとなって消滅しかけるという状況が発生する。そこをヴェルザードに助けられたことをきっかけに、以降ヴェルザードの中で共存するようになる。そして、完全なる不死に至る試みとして、己の心核をヴェルザードに凍結して保護してもらい、本体には複製した記憶を宿らせるようにしてその後も実験をし続けていた。",
