          "戦闘能力は、弱いと自称する一方で、大罪系すら凌駕する権能である『悪徳之王』を所有し、肉体性能も“擬竜体”を使用することで“竜種”に準ずる戦闘能力（魔力は“竜種”と互角、魔素量は劣るもののテスタロッサの10倍近い量）を秘めている。そして特筆すべきは“擬竜体”は破壊されても再度創ることができるという点にある。",
