      "現役を退いて以降は後進の育成に携わり、物語の主要人物である異世界人の“坂口日向”と“神楽坂優樹”の2人の師にもなった。その最後はリムル＝テンペストによって看取られ、彼女たっての願いで自身を召喚した魔王レオンへの想いとその姿は『捕食¹』されることによってリムルに引き継がれた。",
