          "その後、人の世で暮らす方がいいというレオンの考えで“勇者”に保護されたシズは、自由組合の前身となる冒険者互助組合で人の世での生き方を学びながら冒険者になる。“勇者”とは早くに別れることになるが、“抗魔の仮面”を形見として受け継ぎ、冒険者としても英雄として活躍するようになる。“原初の黒”との邂逅もこの時期の出来事である。",
