      "性能はユニークスキルの比ではなく、獲得するには本人の資質と運と偶発的な要素が絡み合う。真なる魔王ですら獲得出来るとは限らない希少な能力。獲得した者は世界の理を知ることで、ユニークレベルであるこの世の法則に由来する魔法より上位の存在になり、魔法による支配など一切を無効化し、ほぼ全ての下位能力が通用しなくなる。",
      "その力の本質は、それを獲得するだけの意思力（心的強度）の強さにあり、究極能力に対抗するには同じく究極能力を所有するか、打ち破るだけの強い意志とそれを支える精神力（エネルギー）が必要となる。意思の力だけで存在しているような精神生命体であれば、究極能力を持たずとも対抗することができ、転じて所有することで精神生命体と同等の存在となれる神話級の武具もまた対抗手段となり得る。",
      "皇帝ルドラは究極覚醒者であるギィ¹に対抗するため、臣下に神話級の武器を貸与したり、究極能力の権能を限定的に付与する『究極付与』を行っていた。究極能力の自力獲得が難しい者に力を与え、裏切りを防止することができる長所から、リムルもこれに似た究極贈与を配下に、究極授与を中庸道化連の同盟相手に与えている。",
