      "取り込んだ対象を再現し、同等の能力を行使することができるスキル。擬態は魔素で出来た黒霧で本体を覆うように構成されるが、情報伝達に若干のタイムラグが生じるため、スライム本体の能力に劣る。これに対し、擬態：人間は黒霧を用いないため、スライムの身体と同等の反応速度を出せる上、手足が生じたことによる運動能力の向上が齎される。また黒霧を用いないため魔素の消費がない。",
      "黒霧を用いる擬態の長所は、擬態した魔物の固有スキルを使用できるようになる（『擬態』しなくても使用できる固有スキルもある）点と、一定量を超えるダメージを負うと擬態は解けるが、本体にダメージは及ばない点にある。ただしダメージを負って擬態が解かれた場合、次に擬態できるようになるまで3分ほどかかるという制限がある。また捕食した魔物の系統が進化した場合、擬態にも適応される。",
      "また擬態できる対象は、情報の解析に成功した対象に限られる。物語序盤でリムルが擬態できるようになったのは、嵐蛇、エビルムカデ、ブラックスパイダー、ジャイアントバット、甲殻蜥蜴、黒嵐星狼、人間、炎巨人。この後、『擬態』と『変質者』の統合分離の合成能力として『万能変化』を獲得したことで、身体の一部分だけ擬態することを可能にし、これの応用として複数の魔物の外見的特徴を再現することが可能になった。また最大の特徴は、全ての魔物の固有スキルを制限なしに自在に操ることが可能な点にある。",
