          "基軸世界の要となる重要拠点であり、倒されると自然と世界が崩壊することから、世界の破滅を目論むフェルドウェイの標的となった。しかし、その防備は万全であり、絶大な力を有するフェルドウェイであっても完全破壊は不可能。ミリムの竜星爆炎覇だけがそれを可能にする。",
