      "東の帝国と忘れられた竜の都に面した魔大陸に位置する魔国。帝国の国境近くには険しい山々があり、山々の間には“死の渓谷”と渓谷の脇道には“妖魔郷”に繋がる裂け目がある。クレイマンの本拠地である居城の周囲には方向感覚を狂わせる霧の迷路（メイズミスト）が立ち込め、城の地下には隠された首都である古代遺跡“アムリタ”が存在する。",
      "元は“魔王”カザリームの支配地だったが、彼がレオンに倒された後、配下だったクレイマンが継承。そのクレイマンもリムルに倒された後は、ミリムの領土として併呑された。",
