          "彼がレオンに倒されると、配下だったクレイマンが継承。そのクレイマンもリムルに倒された後は、ミリムの領土として併呑された。管理はリムルに任されていたが、ミリムの国の首都とも離れており、扱いに困っていたため、天魔大戦にてユウキら中庸道化連を動かす餌として、その譲渡が決定した。",
