          "遺跡は三層構造となっており、現在は黒妖耳長族の住居となっている上階と、幅と高さが２ｍしかない通路が続く迷路になっている中層、草原が広がる明るい光に溢れた大空間に作られた墳墓がある下層で構成される。",
          "下層の墳墓を防衛するための仕掛けが随所に施されており、地脈から壁全体に巡らされたエネルギーによって侵入者の排除と都市の運営が行われている。高度な魔法文明の産物であり、1000年以上劣化することなく稼働し続けていた。",
          "遺跡には効果な宝物やアイテムが多数眠っており、クレイマンの財力の一端は回収した発掘品に依るもの。リムルは回収した調度品は城に展示して博物館へと改装させ、遺跡は観光資源として活用しようと目論んでいた。",
