      "他種族を圧倒する桁違いに膨大な魔素量、単なる攻撃さえも究極に届く威力を誇る攻撃力、究極に至らない物理攻撃はおろか魔法すらも通用しない防御力、心核を砕かれて死亡しても記憶の一部と人格がリセットされるのみで復活することができる正真の不死性。それらを種族の特性として持つ最上位種族。",
      "また四体の“竜種”の長兄である“星王竜”ヴェルダナーヴァが、人間と交わることで生まれた、竜魔人という“竜種”の亜種も存在する。“竜種”との決定的な違いとして不滅の存在ではないとされ、正式には“竜種”に数えられないイレギュラーという扱いだが、“星王竜”の最愛として力の大半を受け継いでおり、その脅威度は“竜種”と同じ特S級とされている。しかし一方で、“星王竜”は大きくその力を失い寿命によってこの世から去ることになった。このことにより“竜種”が人間と子を成すことはタブーとなり、それ故に竜魔人のミリムは唯一無二の存在となっている。",
      "そんなミリムに“星王竜”はペット兼護衛として、精霊竜（エレメンタルドラゴン）を生み出し与えた。この精霊竜が死して混沌竜へと変質した際にばら撒かれた竜の因子によって、世界で龍族（ドラゴン）が生まれるようになり、翻って龍族の起源は精霊竜、更に言えば“星王竜”となる。",
