      "逆に元蜥蜴人族の龍人族は、その最大の特徴を進化によって獲得した翼としており、これによる三次元的な機動力を有する。また獲得する種族固有能力も『竜戦士化』や『竜鱗化』といった使用することでドラゴンの見た目に近づくものが多い。ちなみに『竜鱗化』を逆に駆使することで人の姿に近づくことも可能。",
