          "暴走する魔素は、周囲の物質を取り込んで使用者の肉体を強化する。筋肉は膨張し、その表面を覆う紫の鱗は漆黒に変色し、その柔軟性と硬度は数倍に上がる。それに伴い身長も2割ほど巨大化し、体積と質量が大きく増加することで、攻撃力や防御力、回復力が飛躍的に上昇する。魔素が暴走しているから魔法の使用は出来なくなるものの、吐息等の能力の使用は問題なく可能であり、総合して戦闘能力は数倍に跳ね上がる。",
